<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  /** Optional custom fallback. Receives error + reset fn. */
  fallback?: (error: Error, reset: () => void) => ReactNode;
  /** Called after logging — hook for external error reporters (Sentry, etc.). */
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

const initialState: State = { error: null };

export class ErrorBoundary extends Component<Props, State> {
  state = initialState;

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error(
      "[ErrorBoundary] Uncaught render error\n",
      "Error:    ", error.message,
      "\nStack:    ", error.stack,
      "\nComponent:", info.componentStack,
    );
    this.props.onError?.(error, info);
  }

  reset = () => this.setState(initialState);

  render() {
    const { error } = this.state;

    if (error) {
      return this.props.fallback ? (
        this.props.fallback(error, this.reset)
      ) : (
        <DefaultFallback error={error} onRetry={this.reset} />
      );
    }

    return this.props.children;
  }
}

// ---------------------------------------------------------------------------

interface FallbackProps {
  error: Error;
  onRetry: () => void;
}

function DefaultFallback({ error, onRetry }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.heading}>Something went wrong</h2>
        <p style={styles.message}>{error.message}</p>
        {error.stack && (
          <details style={styles.details}>
            <summary style={styles.summary}>Stack trace</summary>
            <pre style={styles.stack}>{error.stack}</pre>
          </details>
        )}
        <button onClick={onRetry} style={styles.button}>
          Try again
        </button>
      </div>
    </div>
  );
}

const styles = {
  container: {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    minHeight: "100vh",
    padding: "1rem",
    background: "#f9fafb",
    fontFamily: "system-ui, sans-serif",
  } as React.CSSProperties,
  card: {
    maxWidth: 480,
    width: "100%",
    background: "#fff",
    border: "1px solid #e5e7eb",
    borderRadius: 8,
    padding: "2rem",
    boxShadow: "0 1px 4px rgba(0,0,0,.08)",
  } as React.CSSProperties,
  heading: {
    margin: "0 0 .5rem",
    fontSize: "1.25rem",
    fontWeight: 600,
    color: "#111827",
  } as React.CSSProperties,
  message: {
    margin: "0 0 1rem",
    fontSize: ".9rem",
    color: "#dc2626",
    wordBreak: "break-word",
  } as React.CSSProperties,
  details: {
    marginBottom: "1rem",
  } as React.CSSProperties,
  summary: {
    cursor: "pointer",
    fontSize: ".8rem",
    color: "#6b7280",
    userSelect: "none",
  } as React.CSSProperties,
  stack: {
    marginTop: ".5rem",
    padding: ".75rem",
    background: "#f3f4f6",
    borderRadius: 4,
    fontSize: ".75rem",
    color: "#374151",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
  } as React.CSSProperties,
  button: {
    display: "inline-block",
    padding: ".5rem 1.25rem",
    background: "#2563eb",
    color: "#fff",
    border: "none",
    borderRadius: 6,
    fontSize: ".9rem",
    fontWeight: 500,
    cursor: "pointer",
  } as React.CSSProperties,
} as const;
